import{_ as i,l as n,o as a,c as d,v as t,p as s,x as o,d as c,i as l,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"ext4 日志","description":"","frontmatter":{"title":"ext4 日志","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ext4-journal.md","filePath":"cs/ext4-journal.md","lastUpdated":1789023840000}'),p={name:"cs/ext4-journal.md"};function u(m,e,x,f,_,A){const r=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="ext4-日志" tabindex="-1">ext4 日志 <a class="header-anchor" href="#ext4-日志" aria-label="Permalink to &quot;ext4 日志&quot;">​</a></h1><div class="epigraph"><p>日志把元数据更新先顺序写入专用区，提交后再写主文件系统；崩溃后重放日志，不必对整盘 fsck。</p><footer>—— 据 Mathur et al., The new ext4 filesystem, OLS 2007；Linux ext4 文档对 data= 模式的整理</footer></div><p><a href="/cs/fsync">上一课</a>能等待某些块到达，但不能把「目录项与 inode 分配」收成一笔事务。<a href="/cs/buffer-dirty">缓冲</a> 已暴露崩溃窗口。缺口是 <strong>JBD2 日志</strong>：ext4 的三种数据模式如何捆更新，以及它不是数据库栏的 <a href="/cs/wal">WAL</a> 副本——对象是文件系统元数据（及可选数据）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无日志的 FFS 类布局崩溃后，块位图、inode、目录可能互指错误，必须扫描。日志：先写描述「即将做的元数据块」的日志记录，commit，再写原地。重放使元数据回到一致切面。缺口：<code>data=ordered</code>（先数据后元数据，默认）、<code>data=writeback</code>（数据可不排在元数据前）、<code>data=journal</code>（数据也进日志，最慢最严）。本课不发明论文编号。</p><p><span class="marginnote">ordered：避免「inode 已指向新块但块是旧内容」的泄露。writeback 更快，崩溃可能读到垃圾。journal 模式把数据也当事务，性能差，少用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务在内存中收集脏元数据；提交时写入 journal inode 或单独日志设备，打 commit 块，然后允许 checkpoint 把块写回主区域并回收日志空间。<a href="/cs/fsync">fsync</a> 往往迫使当前事务提交。与 VFS 的接头：ext4 的 <code>write_inode</code>/<code>rename</code> 参加事务，而不是各写各的。</p>',8)),(a(),s(h,null,{default:o(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22rename%2Fcreat%22%5D%20--%3E%20TX%5B%22JBD2%20%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20TX%20--%3E%20J%5B%22%E9%A1%BA%E5%BA%8F%E5%86%99%E6%97%A5%E5%BF%97%22%5D%0A%20%20J%20--%3E%20C%5B%22commit%22%5D%0A%20%20C%20--%3E%20CP%5B%22checkpoint%20%E4%B8%BB%20FS%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>日志把随机元数据写换成顺序日志写，崩溃恢复时间与日志大小相关，不与盘容量相关。它不替代页 Cache：数据仍可延迟。不要把 ext4 扩展成 btrfs/XFS 的百科；本课以 ext4 为真实实例，说明「文件系统事务」这一课序。与关系库 WAL 对照：这里没有元组与 REDO 字节语义，只有块映像或描述符。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 extents、延迟分配的全部性能故事，只承认它们改变何时进事务。不保证 USB 盘拔出等于干净 umount。下一课把「一致」从 ext4 机制升成一般问题：先提交什么、fsck 还剩什么。</p><p>后课默认：元数据可以有日志切面。崩溃后系统保证什么、不保证什么，下一课崩溃一致性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ext4 用 JBD2 先记日志再 checkpoint；默认 ordered。</li><li>三种 data= 模式权衡泄露与吞吐。</li><li>一般崩溃语义是下一课。</li><li>出处：Mathur et al., OLS 2007；Linux <code>Documentation/filesystems/ext4/</code>；McKusick 对日志 FS 的背景。</li></ul>',7))])}const S=i(p,[["render",u]]);export{k as __pageData,S as default};
